typedef struct __pfring pfring; /* Forward declaration */

struct __pfring {
  u_int8_t initialized;
  u_int8_t enabled;
  u_int8_t long_header;
  u_int8_t force_timestamp;

  u_int8_t strip_hw_timestamp;
  u_int8_t disable_parsing;
  u_int8_t disable_timestamp;
  u_int8_t ixia_timestamp_enabled;

  u_int8_t __padding_0;
  u_int8_t chunk_mode_enabled;
  u_int8_t userspace_bpf;
  u_int8_t force_userspace_bpf;

  u_int8_t zc_device;
  u_int8_t is_shutting_down;
  u_int8_t socket_default_accept_policy;
  u_int8_t break_recv_loop_ext;

  u_int32_t rss_mode;
  packet_direction direction; /* Specify the capture direction for packets */
  socket_mode mode;

#ifdef BPF_RELEASE
  struct bpf_program
#else
  struct pfring_bpf_program
#endif
    userspace_bpf_filter;

  /* Hardware Timestamp */
  struct {
    u_int8_t force_timestamp;
    u_int8_t is_silicom_hw_timestamp_card;
    u_int8_t enable_hw_timestamp;
    u_int8_t last_hw_timestamp_head_offset;

    struct timespec last_hw_timestamp;
  } hw_ts;

  struct {
    u_int8_t enabled_rx_packet_send;
    struct pfring_pkthdr *last_received_hdr; /* Header of the past packet that has been received on this socket */
  } tx;

  void *priv_data; /* module private data */

  void      (*close)                        (pfring *);
  int       (*stats)                        (pfring *, pfring_stat *);
  int       (*recv)                         (pfring *, u_char**, u_int, struct pfring_pkthdr *, u_int8_t);
  int       (*set_poll_watermark)           (pfring *, u_int16_t);
  int       (*set_poll_watermark_timeout)   (pfring *, u_int16_t);
  int       (*set_poll_duration)            (pfring *, u_int);
  int       (*set_tx_watermark)             (pfring *, u_int16_t);
  int       (*set_channel_id)               (pfring *, u_int32_t);
  int       (*set_channel_mask)             (pfring *, u_int64_t);
  int       (*set_application_name)         (pfring *, char *);
  int       (*set_application_stats)        (pfring *, char *);
  char*     (*get_appl_stats_file_name)     (pfring *ring, char *path, u_int path_len);
  int       (*set_vlan_id)                  (pfring *, u_int16_t);
  int       (*bind)                         (pfring *, char *);
  int       (*send)                         (pfring *, char *, u_int, u_int8_t);
  int       (*send_get_time)                (pfring *, char *, u_int, struct timespec *);
  u_int8_t  (*get_num_rx_channels)          (pfring *);
  int       (*get_card_settings)            (pfring *, pfring_card_settings *);
  int       (*set_sampling_rate)            (pfring *, u_int32_t);
  int       (*set_filtering_sampling_rate)  (pfring *, u_int32_t);
  int       (*set_packet_slicing)           (pfring *, packet_slicing_level, u_int32_t);
  int       (*get_selectable_fd)            (pfring *);
  int       (*set_direction)                (pfring *, packet_direction);
  int       (*set_socket_mode)              (pfring *, socket_mode);
  int       (*set_cluster_consumer)         (pfring *, u_int16_t, u_int16_t, cluster_type, u_int32_t);
  int       (*remove_from_cluster)          (pfring *);
  int       (*set_master_id)                (pfring *, u_int32_t);
  int       (*set_master)                   (pfring *, pfring *);
  u_int32_t (*get_ring_id)                  (pfring *);
  u_int32_t (*get_num_queued_pkts)          (pfring *);
  int       (*get_hash_filtering_rule_stats)(pfring *, hash_filtering_rule *, char *, u_int *);
  int       (*handle_hash_filtering_rule)   (pfring *, hash_filtering_rule *, u_char);
  int       (*purge_idle_hash_rules)        (pfring *, u_int16_t);
  int       (*add_filtering_rule)           (pfring *, filtering_rule *);
  int       (*remove_filtering_rule)        (pfring *, u_int16_t);
  int       (*purge_idle_rules)             (pfring *, u_int16_t);
  int       (*get_filtering_rule_stats)     (pfring *, u_int16_t, char *, u_int *);
  int       (*toggle_filtering_policy)      (pfring *, u_int8_t);
  int       (*enable_rss_rehash)            (pfring *);
  int       (*poll)                         (pfring *, u_int);
  int       (*is_pkt_available)             (pfring *);
  int       (*next_pkt_time)                (pfring *, struct timespec *);
  int       (*next_pkt_raw_timestamp)       (pfring *, u_int64_t *ts);
  int       (*version)                      (pfring *, u_int32_t *);
  int       (*get_bound_device_address)     (pfring *, u_char [6]);
  int       (*get_bound_device_ifindex)     (pfring *, int *);
  int       (*get_device_ifindex)           (pfring *, char *, int *);
  u_int16_t (*get_slot_header_len)          (pfring *);
  int       (*set_virtual_device)           (pfring *, virtual_filtering_device_info *);
  int       (*set_default_hw_action)        (pfring *, generic_default_action_type);
  int       (*add_hw_rule)                  (pfring *, hw_filtering_rule *);
  int       (*remove_hw_rule)               (pfring *, u_int16_t);
  int       (*loopback_test)                (pfring *, char *, u_int, u_int);
  int       (*enable_ring)                  (pfring *);
  int       (*disable_ring)                 (pfring *);
  void      (*shutdown)                     (pfring *);
  int       (*set_bpf_filter)               (pfring *, const char *);
  int       (*remove_bpf_filter)            (pfring *);
  int       (*get_device_clock)             (pfring *, struct timespec *);
  int       (*set_device_clock)             (pfring *, struct timespec *);
  int       (*adjust_device_clock)          (pfring *, struct timespec *, int8_t);
  void      (*sync_indexes_with_kernel)     (pfring *);
  int       (*send_last_rx_packet)          (pfring *, int);
  void      (*flush_tx_packets)             (pfring *);
  int       (*register_zerocopy_tx_ring)    (pfring *, pfring *);
  int       (*recv_chunk)                   (pfring *, void **, pfring_chunk_info *, u_int8_t); 
  int       (*recv_burst)                   (pfring *, pfring_packet_info *, u_int8_t, u_int8_t); 
  int       (*recv_flow)                    (pfring *, pfring_flow_update *, u_int8_t);
  int       (*get_metadata)         	    (pfring *, u_char **, u_int32_t *);
  u_int32_t (*get_interface_speed)	    (pfring *);
  int       (*get_link_type)	            (pfring *);

  /* Silicom Redirector Only */
  struct {
    int8_t device_id;
    int8_t port_id;
  } rdi;

  filtering_mode filter_mode;
  pfring_device_type ft_device_type;  

  /* All devices */
  char *buffer;
  char *slots;
  char *device_name;

  u_int32_t flags;
  u_int32_t caplen;

  u_int16_t slot_header_len;
  u_int16_t mtu /* 0 = unknown */;
  u_int32_t sampling_rate;

  u_int32_t sampling_counter;
  u_int32_t sampling_rnd_shift;

  packet_slicing_level slicing_level;
  u_int32_t slicing_additional_bytes;

  int fd;
  int device_id;

  FlowSlotInfo *slots_info;

  u_int32_t poll_sleep;
  u_int16_t poll_duration;
  u_int8_t promisc;
  u_int8_t ft_enabled; /* PF_RING FT support enabled */

  u_int8_t reentrant;
  u_int8_t break_recv_loop;
  u_int16_t __padding_1;
  u_int32_t num_poll_calls;

  pfring_rwlock_t rx_lock;
  pfring_rwlock_t tx_lock;

  void *ft; /* PF_RING FT handle */

  struct sockaddr_ll sock_tx;

  /* Reflector socket (copy RX packets onto it) */
  pfring *reflector_socket;

  /* Semi-ZC devices (1-copy) */
  pfring *one_copy_rx_pfring;

  pthread_t runtime_manager_thread;
};

typedef struct {
  u_int32_t max_packet_size;
  u_int32_t rx_ring_slots;
  u_int32_t tx_ring_slots;
} pfring_card_settings;

typedef struct {
  u_int64_t recv;
  u_int64_t drop;
  u_int64_t shunt;
} pfring_stat;

typedef enum {
  hardware_and_software = 0,
  hardware_only,
  software_only
} filtering_mode;

typedef enum {
  FULL_PACKET_SLICING = 0,
  L2_SLICING = 2,
  L3_SLICING = 3,
  L4_SLICING = 4
} packet_slicing_level;

typedef enum {
  PCAP_CHUNK,
  PCAP_NSEC_CHUNK,
  PCAPNG_NSEC_CHUNK,
  UNKNOWN_CHUNK_TYPE
} pfring_chunk_type;

typedef struct {
  u_int32_t length;
  pfring_chunk_type type;
} pfring_chunk_info;

typedef struct {
  u_char *data;
  struct timeval ts;     /**< Time stamp */
  u_int16_t caplen;      /**< Packet captured length */
  u_int16_t len;         /**< Packet length */
  u_int32_t flags;       /**< Packet flags (PKT_FLAGS_* defined in pf_ring.h) */
  u_int32_t hash;        /**< Packet hash */
} pfring_packet_info;

#ifndef BPF_RELEASE
struct pfring_bpf_program {
  u_int bf_len; 
  void *bf_insns; 
};
#endif

typedef struct pfring_if {
  char *name;
  char *system_name;
  char *module;
  char *module_version;
  char *sn;
  char mac[6];
  struct { /* Bus ID: "%04X:%02X:%02X.%X", slot, bus, device, function */
    int slot;
    int bus;
    int device;
    int function;
  } bus_id;
  int ifindex;
  int status; /* 1: up, 0: down, -1: unknown */
  int license; /* 1: valid, 0: invalid or not installed */
  time_t license_expiration; /* expiration epoch */
  struct pfring_if *next;
} pfring_if_t;

typedef struct {
  char *name;
  int (*open) (pfring *);
  pfring_if_t *(*findalldevs) (void);
} pfring_module_info;

struct thirdparty_func {
  const char *name;  /* Function name */
  void (*ptr)(void); /* Function pointer */
};

typedef struct {
  pcap_t  *pd;
  u_int8_t is_pcap_file;
  int fd;
} pfring_pcap;

typedef enum {
  rx_only,
  tx_only,
  management_only
} pfring_zc_queue_mode;

typedef struct {
  u_int64_t recv;
  u_int64_t sent;
  u_int64_t drop;
} pfring_zc_stat;

typedef struct {
  u_int32_t tv_sec;
  u_int32_t tv_nsec;
} pfring_zc_timespec;

typedef struct {
  u_int16_t len;
  u_int16_t flags;
  u_int32_t hash;
  pfring_zc_timespec ts;
  u_char user[];
} pfring_zc_pkt_buff;

typedef struct {
  u_int32_t buffer_len;
  u_int32_t metadata_len;
} pfring_zc_queue_info;

typedef struct {
  u_int64_t total_memory;
  u_int32_t buffer_len;
  u_int32_t real_buffer_len;
} pfring_zc_cluster_info;

typedef struct {
  void *base_addr;
  u_int64_t size;
} pfring_zc_cluster_mem_info;

typedef enum {
  round_robin_policy = 0,
  round_robin_bursts_policy
} pfring_zc_recv_policy;

typedef int64_t
(*pfring_zc_filtering_func) (
  pfring_zc_pkt_buff *pkt_handle,
  pfring_zc_queue *in_queue,
  void *user
);

typedef int64_t
(*pfring_zc_distribution_func) (
  pfring_zc_pkt_buff *pkt_handle,
  pfring_zc_queue *in_queue,
  void *user
);

typedef __int128_t
(*pfring_zc_distribution_func_v3) (
  pfring_zc_pkt_buff *pkt_handle,
  pfring_zc_queue *in_queue,
  void *user
);

typedef void
(*pfring_zc_idle_callback) (
);

typedef enum { 
  s2d_direction = 0, /**< Source to destination */
  d2s_direction,     /**< Destination to source */
  PF_RING_FT_FLOW_NUM_DIRECTIONS
} pfring_ft_direction;

typedef enum {
  PFRING_FT_FLOW_STATUS_ACTIVE = 0,     /**< Active flow */
  PFRING_FT_FLOW_STATUS_IDLE_TIMEOUT,   /**< Idle timeout */
  PFRING_FT_FLOW_STATUS_ACTIVE_TIMEOUT, /**< Terminated after the maximum lifetime */
  PFRING_FT_FLOW_STATUS_END_DETECTED,   /**< Terminated for end of flow (e.g. FIN) */
  PFRING_FT_FLOW_STATUS_FORCED_END,     /**< Terminated for external event (shutdown) */
  PFRING_FT_FLOW_STATUS_SLICE_TIMEOUT,  /**< Flow slice timeout */
  PFRING_FT_FLOW_STATUS_OVERFLOW        /**< Exported from those with higher inactivity to make room */
} pfring_ft_flow_status;

typedef struct {
  u_int32_t num_protocols; /**< Number of supported L7 protocols */

  /* Filtering */
  struct {
    pfring_ft_action *protocol_to_action; /**< Action per L7 protocol */
  } match;

  /* Shunting */
  struct {
    u_int8_t default_npkts;      /**< Default number of packets to forward */
    u_int8_t tcp_npkts;          /**< Number of packets to forward in case of TCP */
    u_int8_t udp_npkts;          /**< Number of packets to forward in case of UDP */
    u_int8_t *protocol_to_npkts; /**< Number of packets to forward per L7 protocol */
  } shunt;
} pfring_ft_flow_filter;

typedef struct {
  union {
    u_int8_t   u6_addr8[16];
    u_int16_t  u6_addr16[8];
    u_int32_t  u6_addr32[4];
  } u6_addr;
} __attribute__((packed))
pfring_ft_in6_addr;

typedef struct {
  u_int8_t ihl:4, version:4;
  u_int8_t tos;
  u_int16_t tot_len;
  u_int16_t id;
  u_int16_t frag_off;
  u_int8_t ttl;
  u_int8_t protocol;
  u_int16_t check;
  u_int32_t saddr;
  u_int32_t daddr;
} __attribute__((packed))
pfring_ft_iphdr;

typedef struct {
  u_int32_t ip6_un1_flow;
  u_int16_t ip6_un1_plen;
  u_int8_t ip6_un1_nxt;
  u_int8_t ip6_un1_hlim;
  pfring_ft_in6_addr ip6_src;
  pfring_ft_in6_addr ip6_dst;
} __attribute__((packed))
pfring_ft_ipv6hdr;

typedef struct {
  u_int16_t source;
  u_int16_t dest;
  u_int32_t seq;
  u_int32_t ack_seq;
  u_int16_t res1:4, doff:4, fin:1, syn:1, rst:1, psh:1, ack:1, urg:1, ece:1, cwr:1;
  u_int16_t window;
  u_int16_t check;
  u_int16_t urg_ptr;
} __attribute__((packed))
pfring_ft_tcphdr;

typedef struct {
  u_int16_t source;
  u_int16_t dest;
  u_int16_t len;
  u_int16_t check;
} __attribute__((packed))
pfring_ft_udphdr;

typedef struct {     /* pfring_pkthdr / pcap_pkthdr common struct */
  struct timeval ts; /**< time stamp */
  u_int32_t caplen;  /**< length of captured portion */
  u_int32_t len;     /**< length original packet (off wire) */
} pfring_ft_pcap_pkthdr;

typedef struct {       /* additional packet metadata not available in pcap_pkthdr */
  u_int32_t hash;      /**< packet hash */
  u_int16_t device_id; /**< Source device ID */
  u_int8_t  port_id;   /**< Source device port ID */
  u_int8_t  reserved;  /**< Padding */
} pfring_ft_ext_pkthdr;

typedef struct {
  pfring_ft_pcap_pkthdr *hdr;
  pfring_ft_ext_pkthdr *ext_hdr;
  pfring_ft_direction direction;
  pfring_ft_action action;
  u_int16_t vlan_id;
  u_int8_t ip_version;
  u_int8_t l4_proto;
  u_int16_t payload_len;
  u_int16_t reserved; /* padding */
  union {
    pfring_ft_iphdr   *ip4;
    pfring_ft_ipv6hdr *ip6;
  } l3;
  union {
    pfring_ft_tcphdr *tcp;
    pfring_ft_udphdr *udp;
  } l4;
  const u_char *payload;
} pfring_ft_packet_metadata;

typedef union {
  pfring_ft_in4_addr v4;
  pfring_ft_in6_addr v6;
} pfring_ft_ip_address;

typedef struct {
  u_int16_t master_protocol;  /**< e.g. HTTP */
  u_int16_t app_protocol;     /**< e.g. FaceBook */
  int category;
} pfring_ft_ndpi_protocol;

typedef struct {
  u_int64_t pkts;           /**< Number of packets per direction */
  u_int64_t bytes;          /**< Number of bytes per direction */
  struct timeval first;     /**< Time of first packet seen per direction */
  struct timeval last;      /**< Time of last packet seen per direction */
  u_int8_t tcp_flags;       /**< TCP flags per direction */
  u_int8_t port_id;         /**< Port ID (when provided e.g. MetaWatch) */
  u_int16_t device_id;      /**< Device ID (when provided e.g. MetaWatch) */
} pfring_ft_flow_dir_value;

typedef struct {
  pfring_ft_flow_dir_value direction[PF_RING_FT_FLOW_NUM_DIRECTIONS]; /**< Metadata per flow direction */

  pfring_ft_ndpi_protocol l7_protocol; /**< nDPI protocol */
  u_int32_t tunnel_type; /**< nDPI tunnel type (ndpi_packet_tunnel) */
  u_int32_t tunnel_id;   /**< Tunnel ID (if any) */

  union {
    struct {
      char *query;            /**< DNS query */
      u_int16_t queryType;    /**< DNS query type */
      u_int16_t replyCode;    /**< DNS reply code */
    } dns;

    struct {
      char *serverName;       /**< TLS Server Name */
      u_int8_t *sha1_certificate_fingerprint; /**< SHA-1 Certificate Fingerprint (20-bytes) */
    } tls;

    struct {
      char *serverName;       /**< HTTP Server Name */
      char *url;              /**< HTTP URL */
      u_int16_t responseCode; /**< HTTP response code */
    } http;

    struct {
      u_int8_t type;          /**< ICMP Type */
      u_int8_t code;          /**< ICMP Code */
    } icmp;
  } l7_metadata;

  pfring_ft_flow_status status;
  u_int32_t flags;            /**< See PFRING_FT_FLOW_STATUS_* */

  u_char *user;               /**< User metadata: this points to the end of
                               * the same struct usually. In case of flow
                               * slice this points to the original flow's
                               * user data. */
} pfring_ft_flow_value;

typedef struct {
  u_int64_t active_flows;     /**< Number of currently active flows */
  u_int64_t flows;            /**< Number of total flows */
  u_int64_t err_no_room;      /**< Flow creation errors due to no room left in the flow table */
  u_int64_t err_no_mem;       /**< Flow creation errors due to memory allocation failures */
  u_int64_t disc_no_ip;       /**< Number of packets not processed because L3 header was missing */
  u_int64_t max_lookup_depth; /**< Maximum collition list depth during flow lookup */
  u_int64_t packets;          /**< Number of processed packets */
  u_int64_t bytes;            /**< Total number of packet bytes */
} pfring_ft_stats;

typedef struct {
  u_int32_t num_buffered_records;
  u_int32_t exported_flows;
  u_int32_t dropped_flows;
} pfring_ft_export_stats;

typedef void
(*pfring_ft_export_list_func) (
  pfring_ft_list *flows_list,
  void *user
);

typedef void
(*pfring_ft_export_flow_func) (
  pfring_ft_flow *flow,
  void *user
);

typedef void
(*pfring_ft_flow_packet_func) (
  const u_char *data,
  pfring_ft_packet_metadata *metadata,
  pfring_ft_flow *flow,
  void *user
);

struct nbpf_in6_addr {
  union {
    u_int8_t   u6_addr8[16];
    u_int16_t  u6_addr16[8];
    u_int32_t  u6_addr32[4];
  } u6_addr;  /* 128-bit IP6 address */
};

PACKED_ON typedef union {
  struct nbpf_in6_addr v6;
  u_int32_t v4;
} PACKED_OFF
nbpf_ip_addr;

PACKED_ON typedef struct {
  u_int8_t header;
  u_int8_t protocol;
  u_int8_t direction;
  u_int8_t address;
} PACKED_OFF
nbpf_qualifiers_t;

PACKED_ON typedef struct {
  int protocol;
  u_int16_t offset;
  u_int8_t mask;
} PACKED_OFF
nbpf_arth_t;

PACKED_ON typedef struct nbpf_node {
  int type;
  int level;
  nbpf_qualifiers_t qualifiers;

  u_int8_t not_rule;

  u_int16_t device_id;
  u_int16_t interface_id;

  u_int8_t vlan_id_defined, mpls_label_defined;
  u_int8_t __padding;
  u_int16_t vlan_id;
  u_int16_t mpls_label;
  u_int8_t mac[6];
  u_int8_t ip6[16], mask6[16];
  u_int32_t ip, mask;
  u_int16_t port_from, port_to;
  u_int16_t protocol;
  u_int16_t l7protocol;

  struct { /* e.g. udp[10] & 0x0f == 5 */
    u_int16_t protocol;
    u_int16_t offset;
    u_int8_t mask;
    u_int8_t relop;
    u_int8_t value;
  } byte_match;

  char *custom_key;
  char *custom_value;

  struct nbpf_node *l;
  struct nbpf_node *r;
} PACKED_OFF
nbpf_node_t;

PACKED_ON typedef struct {
  nbpf_node_t *root;
  int compatibility_level; /* external use */

  /* Default action - This is used when building hw rules to set the default policy
     - No rules: default pass (pass all)
     - All not rules: default pass (pass all except ..)
     - All pass rules or mixed: default drop (drop all except ..)
   */
  int default_pass;

  /* Callback for custom primitive node match 
   * Return 1 in case of match, 0 otherwise */ 
  nbpf_custom_node_callback custom_callback;

  /* Callback for Local/Remote match
   * Return 1 on local, 0 on remote */
  nbpf_ip_locality_callback locality_callback;
} PACKED_OFF
nbpf_tree_t;

PACKED_ON typedef struct nbpf_pkt_info_tuple {
  u_int16_t eth_type;
  u_int8_t ip_version;
  u_int8_t l3_proto, ip_tos;
  nbpf_ip_addr ip_src, ip_dst;
  u_int16_t l4_src_port, l4_dst_port;
} PACKED_OFF
nbpf_pkt_info_tuple_t;

PACKED_ON typedef struct {
  u_int16_t device_id, interface_id;
  u_int8_t  dmac[6], smac[6];
  u_int16_t vlan_id, vlan_id_qinq;
  u_int16_t master_l7_proto, l7_proto;
  nbpf_pkt_info_tuple_t tuple;
  nbpf_pkt_info_tuple_t tunneled_tuple;
} PACKED_OFF
nbpf_pkt_info_t;

PACKED_ON typedef struct nbpf_rule_core_fields_byte_match {
    u_int16_t protocol;
    u_int16_t offset;
    u_int8_t mask;
    u_int8_t relop;
    u_int8_t value;
    struct nbpf_rule_core_fields_byte_match *next;
} PACKED_OFF
nbpf_rule_core_fields_byte_match_t;

PACKED_ON typedef struct {
